import math

def clamp_unit(x: float) -> float | None:
    if math.isnan(x) or x < 0:
        return None
    elif 0 <= x <= 1:
        return x
    elif 1 < x <= 10:
        return x / 10
    elif 10 < x <= 100:
        return x / 100
    else:
        return None

def test_clamp_unit():
    assert clamp_unit(0.5) == 0.5
    assert clamp_unit(7) == 0.7
    assert clamp_unit(42) == 0.42
    assert clamp_unit(123) is None
    assert clamp_unit(-1) is None
    assert clamp_unit(math.nan) is None
